import{_ as o,o as c,c as a,ae as d}from"./chunks/framework.BD9pLfSD.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"面试/09.sourceMap相关.md","filePath":"面试/09.sourceMap相关.md","lastUpdated":1769081193000}'),r={name:"面试/09.sourceMap相关.md"};function p(s,e,t,u,_,n){return c(),a("div",null,[...e[0]||(e[0]=[d('<h3 id="sourcemap是什么-有什么作用-在生产环境怎么用" tabindex="-1">Sourcemap是什么？有什么作用？在生产环境怎么用？ <a class="header-anchor" href="#sourcemap是什么-有什么作用-在生产环境怎么用" aria-label="Permalink to &quot;Sourcemap是什么？有什么作用？在生产环境怎么用？&quot;">​</a></h3><p><code>Sourcemap</code> 本质上是一个信息文件，里面储存着代码转换前后的对应位置信息。它记录了转换压缩后的代码所对应的转换前的源代码位置，是源代码和生产代码的映射。</p><p><code>Sourcemap</code> 解决了在打包过程中，代码经过压缩，去空格以及 <code>babel</code> 编译转化后，由于代码之间差异性过大，造成无法<code>debug</code>的问题，简单说 <code>Sourcemap</code> 构建了处理前以及处理后的代码之间的一座桥梁，方便定位生产环境中出现 <code>bug</code> 的位置。</p><p>因为现在的前端开发都是模块化、组件化的方式，在上线前对 js 和 css 文件进行合并压缩容易造成混淆。 如果对这样的线上代码进行调试，肯定不切实际，<code>sourceMap</code> 的作用就是能够让浏览器的调试面版将生成后的代码映射到源码文件当中，开发者可以在源码文件中 debug，这样就会让程序员调试轻松、简单很多。</p><p><code>Sourcemap</code> 的种类有很多， 在生产环境下可以用<code>process.env</code>判断一下。</p><p><code>webpack</code>中可以在<code>devtool</code>中设置, 在开发环境中可以配置<code>devtool</code>为<code>cheap-module-source-map</code>，方便调试。 生产环境下建议采用<code>none</code>的方式，这样做不暴露源代码。或者是<code>nosources-source-map</code> 的方式，既可以定位源代码位置，又不暴露源代码。</p>',6)])])}const i=o(r,[["render",p]]);export{l as __pageData,i as default};
